  时，state会陷入周期，系统没能表现出混沌性。因此，这个加密是周期性的异或，而非一次一密。而周期性的异或加上明文可打印的条件，是可以逐个位置减少密钥空间，乃至恢复密钥的。
我们小心求证一下，对于给定的参数u=3.5699456，随机选取1000个种子，每个种子生成1048576个字节的密钥流，验证是否存在较短的周期。
import randomfrom decimal import Decimal, getcontextfrom gmssl.sm3 import sm3, funcfrom tqdm import trange, tqdmgetcontext().prec = 100def sm3_hash(msg):    msg = func.bytes_to_list(msg)    hash_value = sm3.sm3_hash(msg)    return bytes.fromhex(hash_value)class RC2147483648:    def __init__(self, seed):        if not (Decimal(0) &lt; seed &lt; Decimal(1)):            raise ValueError(&quot;Seed必须在 (0, 1) 范围内&quot;)        self.state = seed        self.u = Decimal(&#x27;3.5699456&#x27;)    def getByte(self):        t = str(self.state)        bs = sm3_hash(t.encode())        return bs[-1]    def next(self):        self.state = self.state * self.u * (Decimal(1) - self.state)        if not (Decimal(0) &lt; self.state &lt; Decimal(1)):            self.state = Decimal(random.randint(1, 999999)) / Decimal(1000000)        return self.state    def getSstream(self, n):        ss = b&#x27;&#x27;        for _ in trange(n, desc=&quot;Generating S-stream&quot;):            ss += self.getByte().to_bytes(1, &#x27;big&#x27;)            self.next()        return ss    def encrypted(self, pt):        out = b&#x27;&#x27;        Sstream = self.getSstream(len(pt))        for i in range(len(pt)):            out += (pt[i] ^ Sstream[i]).to_bytes(1, &#x27;big&#x27;)        return outdef check_short_cycle(seed, max_iter, period_limit):    &quot;&quot;&quot;    检查给定种子是否在 max_iter 步内    产生一个长度小于 period_limit 的循环。    使用字典来跟踪 &quot;状态 -&gt; 迭代次数&quot;    &quot;&quot;&quot;    rc = RC2147483648(seed)    states_seen = &#123;&#125;  # 字典: &#123;state: iteration_number&#125;    for i in range(max_iter):        current_state = rc.next()        if current_state in states_seen:            # 发现循环！            first_seen_at = states_seen[current_state]            cycle_len = i - first_seen_at            if cycle_len &lt; period_limit:                # 发现了短周期                return True, cycle_len  # (找到短周期, 周期长度)            else:                # 周期不够短，但也算找到了                return False, cycle_len # (未找到短周期, 周期长度)                states_seen[current_state] = i    # 在 max_iter 步内未找到任何循环    return False, None  # (未找到短周期, 未知周期)def run_test_suite(num_seeds, max_iter, period_limit):    &quot;&quot;&quot;    运行完整的测试套件    &quot;&quot;&quot;    print(f&quot;--- 开始周期性测试 ---&quot;)    print(f&quot;测试种子数: &#123;num_seeds&#125;&quot;)    print(f&quot;最大迭代次数/种子: &#123;max_iter&#125; (2^&#123;int(max_iter.bit_length()-1)&#125;)&quot;)    print(f&quot;短周期阈值: &#123;period_limit&#125; (2^&#123;int(period_limit.bit_length()-1)&#125;)&quot;)    print(f&quot;Decimal 精度: &#123;getcontext().prec&#125; 位&quot;)    print(&quot;-&quot; * 20)    short_cycle_count = 0    found_cycles = []    # 使用tqdm显示总进度    for i in tqdm(range(num_seeds), desc=&quot;Testing Seeds&quot;):        # 生成一个随机的、高精度的种子 (0, 1)        # 我们用字符串来确保精度        rand_str = &#x27;0.&#x27; + &#x27;&#x27;.join(random.choices(&#x27;0123456789&#x27;, k=getcontext().prec - 1))        seed = Decimal(rand_str)                # 确保种子有效        if seed == Decimal(0) or seed == Decimal(1):            continue        try:            is_short, cycle_len = check_short_cycle(seed, max_iter, period_limit)                        if is_short:                short_cycle_count += 1                found_cycles.append((str(seed), cycle_len))                except ValueError as e:            # 捕获 &quot;Seed必须在 (0, 1) 范围内&quot; 的错误（如果状态逸出）            tqdm.write(f&quot;种子 &#123;str(seed)[:10]&#125;... 在迭代中失效: &#123;e&#125;&quot;)        except Exception as e:            tqdm.write(f&quot;种子 &#123;str(seed)[:10]&#125;... 发生未知错误: &#123;e&#125;&quot;)    print(&quot;\n--- 测试结果 ---&quot;)    print(f&quot;在 &#123;num_seeds&#125; 个随机种子中，&quot;)    print(f&quot;**发现 &#123;short_cycle_count&#125; 个种子的周期小于 &#123;period_limit&#125;。**&quot;)    if short_cycle_count &gt; 0:        print(&quot;\n发现短周期的种子（部分示例）:&quot;)        for seed_str, length in found_cycles[:10]:            print(f&quot;  - 种子 (前10位): &#123;seed_str[:12]&#125;... \t周期: &#123;length&#125;&quot;)if __name__ == &quot;__main__&quot;:    NUM_SEEDS = 1000        # 你要求的种子数量    MAX_ITER = 2**20        # 1,048,576    PERIOD_LIMIT = 2**15    # 32,768    run_test_suite(NUM_SEEDS, MAX_ITER, PERIOD_LIMIT)
经过测试，在1000次实验中，1000次的周期都小于32768，进一步测试表明周期均为4096。这说明了虽然我们不知道题目使用的seed，但是大概率周期同样是4096，我们根据这个周期进行破解。
我们已知：flag前后均有一个0x00，明文最后四个字节是0x00，其余字符均为可打印字符。因此，对于每个位置，遍历0到255，对于这个位置对应的所有密文，异或这个密钥应该是可打印明文（或者刚才那几个特定的位置上是0x00）。如果出现不可打印的明文，则这个密钥一定不正确。对于有0x00存在的位，还有更高效的策略：由于0x00异或任何数都不改变另一个数，所以这个位置的密文直接就是密钥。经过大量密文的筛选，每个位置上的候选密钥都不会太多。
由于密文长为1048619，可打印的随机字符串长为1048576，0x00共有6个，因此flag一共37位。因此我们只需要这37个位置的密钥就足够了，其他位置即使密钥不能完全确定也不影响。
需要注意的是，周期为4096并不代表从一开始整个加密器就进入了周期。事实上，加密器会先运行一段时间才陷入循环。因此，密文开头的数据需要舍弃。在将尽可能多的数据纳入分析后，只有最前的172068个字节不能保留。如果留下它们，则会引起冲突，找不到能使所有密文都变成可打印明文的密钥了。
# 策略:# 1. 使用 KPA (flag&#123;, 0x00s) (约束 1)# 2. 使用 flag 之后的可打印数据 (约束 2a)# 3. 使用 flag 之前约 60% 的可打印数据 (约束 2b)# 4. 在递归求解时，假设 flag 主体也是可打印的 (约束 3)# 5. 只求解 flag 主体必需的密钥import stringimport sysfrom tqdm import tqdmfrom math import prod# --- 常量 ---CT_FILE = &#x27;ciphertext&#x27;PERIOD = 4096def main():    print(f&quot;[*] 正在加载密文文件: &#123;CT_FILE&#125;&quot;)    try:        with open(CT_FILE, &#x27;rb&#x27;) as f:            ct = f.read()        L_ct = len(ct)        print(f&quot;[*] 密文加载成功，总长度: &#123;L_ct&#125; 字节&quot;)    except FileNotFoundError:        print(f&quot;[!] 错误: 密文文件 &#x27;&#123;CT_FILE&#125;&#x27; 未找到。&quot;)        sys.exit(1)    # --- 1. 定义所有常量和范围 ---    L_RANDOM_MSG_TOTAL = 1048576    L_RANDOM_PART1 = L_RANDOM_MSG_TOTAL // 2  # 524288    L_KNOWN_PLAINTEXT_BYTES = 6    L_flag = L_ct - L_RANDOM_MSG_TOTAL - L_KNOWN_PLAINTEXT_BYTES    if L_flag &lt; 0:        print(f&quot;[!] 错误: 密文长度 &#123;L_ct&#125; 太短。&quot;)        sys.exit(1)    print(f&quot;[*] 周期 $p=&#123;PERIOD&#125;$。推断: len(flag) = &#123;L_flag&#125; 字节&quot;)    L_CONTAMINANT_MID = L_flag + 2    # `flag` 的范围 (不包括 b&#x27;\x00flag&#123;&#x27;)    flag_body_start_idx = L_RANDOM_PART1 + 1 + 5  # 5 for &#x27;flag&#123;&#x27;    flag_body_end_idx = flag_body_start_idx + (L_flag - 5)    flag_body_ct = ct[flag_body_start_idx: flag_body_end_idx]    # 范围 2a : flag 之后的数据    slice2_start = L_RANDOM_PART1 + L_CONTAMINANT_MID    slice2_end = L_ct - 4    slice2_range = (slice2_start, slice2_end)    # 范围 2b : flag 之前的数据    slice1_reliable_start = int(L_RANDOM_PART1 * 0.3281937)  # 524288 * 0.3281937 = 172068，至少需要排除这么多，否则无解    slice1_reliable_end = L_RANDOM_PART1    slice1_reliable_range = (slice1_reliable_start, slice1_reliable_end)    print(f&quot;[*] &#x27;约束 2&#x27; 将使用两个数据范围:&quot;)    print(f&quot;    - 暂态后 (slice1) 范围: &#123;slice1_reliable_range&#125;&quot;)    print(f&quot;    - 稳定 (slice2) 范围: &#123;slice2_range&#125;&quot;)    # 约束 3 (Printable flag) 的范围    PRINTABLE_BYTES = set(string.printable.encode(&#x27;ascii&#x27;))    # 随机数据部分不包含 0x00    PRINTABLE_ONLY = PRINTABLE_BYTES - &#123;0&#125; if 0 in PRINTABLE_BYTES else PRINTABLE_BYTES    # --- 2. 建立所需密钥的候选列表 ---    # 获取 flag_body (flag&#123;...&#125; 中 ... 的部分) 所需的密钥位置    flag_body_key_positions = []    for i in range(len(flag_body_ct)):        flag_body_key_positions.append((flag_body_start_idx + i) % PERIOD)    unique_key_positions = set(flag_body_key_positions)    # key_candidates: 存储每个 *必需* 密钥位置的可能值    key_candidates = &#123;pos: set(range(256)) for pos in unique_key_positions&#125;    print(f&quot;[*] Flag 主体 (&#123;len(flag_body_ct)&#125; 字节) 依赖于 &#123;len(unique_key_positions)&#125; 个唯一的密钥字节。&quot;)    # --- 3. 应用约束 1 (已知明文) ---    print(f&quot;[*] 正在应用“约束 1”(已知明文)...&quot;)    known_pt = &#123;&#125;    # b&#x27;\x00&#x27; at start of flag block    known_pt[L_RANDOM_PART1] = 0x00    # b&#x27;flag&#123;&#x27;    prefix = b&#x27;flag&#123;&#x27;    for i in range(len(prefix)):        known_pt[L_RANDOM_PART1 + 1 + i] = prefix[i]    # b&#x27;\x00&#x27; at end of flag block    known_pt[L_RANDOM_PART1 + 1 + L_flag] = 0x00    # b&#x27;\x00\x00\x00\x00&#x27; at end of file    for i in range(4):        known_pt[L_ct - 4 + i] = 0x00    # 用已知明文过滤 key_candidates    for idx, pt_byte in known_pt.items():        pos = idx % PERIOD        if pos in key_candidates:            key_byte = ct[idx] ^ pt_byte            # 这是一个强约束，我们只保留这一个值            key_candidates[pos].intersection_update(&#123;key_byte&#125;)    # --- 4. 应用约束 2 (Printable msg) ---    print(f&quot;[*] 正在应用“约束 2”(Printable msg parts)...&quot;)    def filter_set_with_byte(guesses_set, ct_byte, constraints_set):        &quot;&quot;&quot;辅助函数：用一个密文字节过滤一个猜测集&quot;&quot;&quot;        # 如果猜测集已经只有一个值，就跳过        if len(guesses_set) &lt;= 1:            return        current_guesses = guesses_set.copy()        for k_guess in current_guesses:            # 随机数据不包含 0x00，所以使用 PRINTABLE_ONLY            if (ct_byte ^ k_guess) not in PRINTABLE_ONLY:                guesses_set.remove(k_guess)    # 遍历所有需要的密钥位置    for pos in tqdm(key_candidates.keys(), desc=&quot;Filtering keys&quot;):        if len(key_candidates[pos]) == 1:            continue        # 遍历 msg_part1 (后 60%)        start_idx = slice1_reliable_range[0]        end_idx = slice1_reliable_range[1]        # (高效遍历, 从 &#x27;pos&#x27; 在范围内的第一个索引开始)        first_i = start_idx + (pos - start_idx) % PERIOD        for i in range(first_i, end_idx, PERIOD):            filter_set_with_byte(key_candidates[pos], ct[i], PRINTABLE_ONLY)        # 遍历 msg_part2        start_idx = slice2_range[0]        end_idx = slice2_range[1]        first_i = start_idx + (pos - start_idx) % PERIOD        for i in range(first_i, end_idx, PERIOD):            filter_set_with_byte(key_candidates[pos], ct[i], PRINTABLE_ONLY)    # --- 5. 检查结果并进行暴力破解 ---    print(&quot;\n[*] 约束应用完成。正在检查剩余可能性...&quot;)    total_solutions = 1    has_contradiction = False    unresolved_keys = &#123;&#125;  # 存储多解的密钥    for pos in unique_key_positions:        count = len(key_candidates[pos])        if count == 0:            print(f&quot;[!] 致命错误: 密钥位置 &#123;pos&#125; 没有可能的解！(出现矛盾)&quot;)            has_contradiction = True        elif count &gt; 1:            print(f&quot;[!] 警告: 密钥位置 &#123;pos&#125; 仍有 &#123;count&#125; 个解&quot;)            unresolved_keys[pos] = count        # 使用 math.prod 来避免浮点数问题        total_solutions = prod([len(key_candidates[pos]) for pos in unique_key_positions])    if has_contradiction:        print(&quot;[!] 无法解密。请检查周期或已知明文/暂态假设。&quot;)        sys.exit(1)    print(f&quot;[*] 总可能性空间: &#123;total_solutions&#125; 个解。&quot;)    if total_solutions &gt; 500000:  # 设置一个安全阈值        print(&quot;[!] 解空间太大，无法全部打印。&quot;)        print(f&quot;   未唯一确定的密钥: &#123;unresolved_keys&#125;&quot;)        print(&quot;   请考虑增加更多约束&quot;)        sys.exit(1)    print(&quot;\n==================== 可能的 FLAG ====================&quot;)    # 递归函数来探索所有可能的解    solution_count = 0    def solve(flag_body_idx, current_flag_bytes):        nonlocal solution_count        # 如果解完了，打印        if flag_body_idx == len(flag_body_ct):            try:                # 打印完整的 flag                print(&quot;flag&#123;&quot; + current_flag_bytes.decode(&#x27;ascii&#x27;))                solution_count += 1            except UnicodeDecodeError:                pass  # 忽略无效的 (非 ascii) flag            return        pos = flag_body_key_positions[flag_body_idx]        c_byte = flag_body_ct[flag_body_idx]        # 遍历这个位置的所有可能性        for k_guess in key_candidates[pos]:            pt_byte = c_byte ^ k_guess            # 应用约束 3 (Printable Flag)            if pt_byte in PRINTABLE_BYTES:                solve(flag_body_idx + 1, current_flag_bytes + bytes([pt_byte]))    # 开始递归    solve(0, b&#x27;&#x27;)    print(&quot;=====================================================&quot;)    print(f&quot;[*] 搜索完成。共找到 &#123;solution_count&#125; 种符合 &#x27;printable-flag&#x27; 约束的解。&quot;)    if solution_count == 0 and total_solutions &gt; 0:        print(&quot;[!] 未找到符合 &#x27;printable&#x27; 约束的解。也许 flag 包含非打印字符？&quot;)if __name__ == &quot;__main__&quot;:    main()
