使用 lattice-based-cryptanalysis 中的HNP脚本，参数稍加修改。
# from /lbc_toolkit/problems/hidden_number_problem.sagedef hnp(p, T, A, B, lattice_reduction=None, verbose=False):    r&quot;&quot;&quot;    Returns the solution of the given hidden number problem instance. i.e. finds    `\alpha \in [1, p - 1]` satisfying    .. MATH::        \beta_i - t_i \alpha + a_i \equiv 0 \pmod p    where the `t_i` and `a_i` are given by ``T`` and ``A``, and the `\beta_i`    are bounded above by ``B``.    The implementation follows the algorithm as described in section 2.5 of [1].    INPUT:    - ``p`` -- The modulus `p` as described above.    - ``T`` -- A list of integers representing the `t_i`.    - ``A`` -- A list of integers representing the `a_i`.    - ``B`` -- The upper bound on the `\beta_i` as described above.    OUTPUT:    The integer `\alpha` which is a solution to the HNP instance. If no solution    could be found, None is returned.    REFERENCES:    [1] Martin R. Albrecht and Nadia Heninger. *On Bounded Distance Decoding with Predicate:    Breaking the “Lattice Barrier” for the Hidden Number Problem.*    In Lecture Notes in Computer Science, p. 528--558. Springer, 2021.    https://link.springer.com/chapter/10.1007/978-3-030-77870-5_19    &quot;&quot;&quot;    verbose = (lambda *a: print(&#x27;[hnp]&#x27;, *a)) if verbose else lambda *_: None    if len(T) != len(A):        raise ValueError(f&#x27;Expected number of t_i to equal number of a_i, but got &#123;len(T)&#125; and &#123;len(A)&#125;.&#x27;)    m = len(T)    M = p * Matrix.identity(QQ, m)    M = M.stack(vector(T))    M = M.stack(vector(A))    M = M.augment(vector([0] * m + [B / p] + [0]))    M = M.augment(vector([0] * (m + 1) + [B]))    M = M.dense_matrix()    verbose(&#x27;Lattice dimensions:&#x27;, M.dimensions())    lattice_reduction_timer = cputime()    if lattice_reduction:        M = lattice_reduction(M)    else:        M = M.LLL()    verbose(f&#x27;Lattice reduction took &#123;cputime(lattice_reduction_timer):.3f&#125;s&#x27;)    for row in M:        if row[-1] == -B:            alpha = (row[-2] * p / B) % p            if all((beta - t * alpha + a) % p == 0 for beta, t, a in zip(row[:m], T, A)):                return alpha        if row[-1] == B:            alpha = (-row[-2] * p / B) % p            if all((beta - t * alpha + a) % p == 0 for beta, t, a in zip(-row[:m], T, A)):                return alpha    return Nonep =  = [, , , , , ]A = [96354217664113218713079763550257275104215355845815212539932683912934781564627, 30150406435560693444237221479565769322093520010137364328243360133422483903497, 70602489044018616453691889149944654806634496215998208471923855476473271019224, 48151736602211661743764030367795232850777940271462869965461685371076203243825, 103913167044447094369215280489501526360221467671774409004177689479561470070160, 84110063463970478633592182419539430837714642240603879538426682668855397515725]B = 2^256Binv = inverse_mod(B, p)Tprime = [i*Binv for i in T]Aprime = [i*Binv for i in A]Bactual = 2^520 # m填充后有44*8+160=512bit，因此取一个略大的B，覆盖betasol = hnp(p, Tprime, Aprime, Bactual, verbose=True)print(&#x27;  Found  solution:&#x27;, sol, end=&#x27;\n\n&#x27;)if sol:    from Crypto.Util.number import long_to_bytes    print(long_to_bytes(sol))
