from ecdsa import SECP256k1import hashlibHASH = lambda x:hashlib.sha256(x.encode()).digest()from Crypto.Cipher import AESfrom Crypto.Util.Padding import unpadfrom Crypto.Util.number import *n = SECP256k1.order#n = 115792089237316195423570985008687907852837564279074904382605163141518161494337r1, s1 = (73867508891928190681343925640843782202723994546540458470096489848436548078703, 39122410553077468025764465969264486973131636681494257798507379902488217704193) #msg:&#x27;123&#x27;r2, s2 = (73867508891928190681343925640843782202723994546540458470096489848436548078703, 21206587815726333302993960460117790620241939923440514755146963234252437892445) #msg:&#x27;321&#x27;assert r1 == r2k = (bytes_to_long(HASH(&#x27;123&#x27;))-bytes_to_long(HASH(&#x27;321&#x27;)))*inverse_mod((s1-s2),n)%nd = (k*s1-bytes_to_long(HASH(&#x27;123&#x27;)))*inverse_mod(r1,n)%naes_key = hashlib.sha256(str(d).encode()).digest()cipher = AES.new(aes_key, AES.MODE_ECB)flag = unpad(cipher.decrypt(long_to_bytes(0x90ca6df74f9c1ca09dde32f6dd3b1b60eb3a21ec86fea87e4462d5c052fea1f95164c4b70ba830b9a4ae40785f1ed78d)), 16)print(flag)
