这密码学有力气。
import socketserverimport jsonimport osimport randomimport hashlibimport sysfrom ecdsa import SECP256k1, SigningKeyfrom ecdsa.util import sigencode_string, sigdecode_stringclass RNG:    def get_k(self):        return random.getrandbits(128)class Task(socketserver.BaseRequestHandler):    def handle(self):        self.request.settimeout(60)        rng = RNG()        sk = SigningKey.generate(curve=SECP256k1)        vk = sk.verifying_key        try:            self.send(json.dumps(&#123;                &quot;x&quot;: vk.pubkey.point.x(),                &quot;y&quot;: vk.pubkey.point.y()            &#125;))            for _ in range(60):                data = self.request.recv(1024).strip()                if not data:                    break                req = json.loads(data.decode())                op = req.get(&#x27;op&#x27;)                if op == &#x27;sign&#x27;:                    msg = req.get(&#x27;msg&#x27;)                    if msg == &#x27;give_me_flag&#x27;:                        self.send(json.dumps(&#123;&quot;error&quot;: &quot;forbidden&quot;&#125;))                        continue                    h = hashlib.sha256(msg.encode()).digest()                    k = rng.get_k()                    sig = sk.sign_digest(h, k=k, sigencode=sigencode_string)                    r = int.from_bytes(sig[:32], &#x27;big&#x27;)                    s = int.from_bytes(sig[32:], &#x27;big&#x27;)                    self.send(json.dumps(&#123;                        &quot;r&quot;: hex(r),                        &quot;s&quot;: hex(s),                        &quot;h&quot;: hex(int.from_bytes(h, &#x27;big&#x27;))                    &#125;))                elif op == &#x27;flag&#x27;:                    r = int(req.get(&#x27;r&#x27;), 16)                    s = int(req.get(&#x27;s&#x27;), 16)                    sig = r.to_bytes(32, &#x27;big&#x27;) + s.to_bytes(32, &#x27;big&#x27;)                    h = hashlib.sha256(b&#x27;give_me_flag&#x27;).digest()                    if vk.verify_digest(sig, h, sigdecode=sigdecode_string):                        self.send(json.dumps(&#123;&quot;flag&quot;: os.getenv(&quot;GZCTF_FLAG&quot;, &quot;GZCTF&#123;test_flag&#125;&quot;)&#125;))                        break                    else:                        self.send(json.dumps(&#123;&quot;error&quot;: &quot;invalid&quot;&#125;))                        break        except:            pass        finally:            self.request.close()    def send(self, data):        self.request.sendall(data.encode() + b&#x27;\n&#x27;)class Server(socketserver.ThreadingMixIn, socketserver.TCPServer):    allow_reuse_address = Trueif __name__ == &quot;__main__&quot;:    server = Server((&quot;0.0.0.0&quot;, 9999), Task)    server.serve_forever()
另一道ECDSA，疑似没活了，和上面那个Hide都是咨询了AI得到的方案，Gemini还是太权威了。
在60次交互内可以选择获取除了'give_me_flag'以外的任意签名，或者自己给这条消息签名再发送给服务器。在没有签名的情况下伪造签名，那只能是签名方案有漏洞了。
看看这次的k，它是一个128bit的随机数，虽然是random库生成的但是信息远远少于19968bit，况且我们还没法知道k。但是曲线SECP256k1的阶有256位，此处的k远远小于它，高128位始终是0。这种情况属于有偏的nonce，网上的文章说偏差甚至小于一位就可以攻破，这很可怕不是吗。
