  。好巧不巧这个攻击在 lattice-based-cryptanalysis 上也有实现，但是我连与服务器交互都不想写，于是让Gemini完全重写了一份。
#!/usr/bin/env sageimport sysimport jsonimport hashlibfrom sage.all import *from pwn import *from ecdsa import SigningKey, SECP256k1from ecdsa.util import sigencode_string, sigdecode_string# ================= 配置部分 =================HOST = &quot;ctf.furryctf.com&quot;PORT = 35616ORDER = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141NONCE_BITS = 128COLLECT_COUNT = 10  # 签名总数ATTACK_COUNT = 6    # 用于攻击的样本数，剩下的用来验证私钥正确性# ================= 交互与辅助函数 =================def get_signatures(io, count):    &quot;&quot;&quot;从服务器获取签名&quot;&quot;&quot;    samples = []    log.info(f&quot;正在采集 &#123;count&#125; 组签名...&quot;)        for i in range(count):        msg = f&quot;req_&#123;i&#125;&quot;        payload = json.dumps(&#123;&quot;op&quot;: &quot;sign&quot;, &quot;msg&quot;: msg&#125;)        io.sendline(payload.encode())                resp = json.loads(io.recvline().decode())                # 提取数据 (注意：服务器返回的 h 是 hash 的整数值)        samples.append(&#123;            &quot;r&quot;: int(resp[&#x27;r&#x27;], 16),            &quot;s&quot;: int(resp[&#x27;s&#x27;], 16),            &quot;h&quot;: int(resp[&#x27;h&#x27;], 16),            &quot;msg&quot;: msg        &#125;)    log.success(f&quot;采集完成，共 &#123;len(samples)&#125; 组数据&quot;)    return samplesdef verify_candidate(d, samples, pub_tuple):    &quot;&quot;&quot;验证候选私钥&quot;&quot;&quot;    try:        # 1. 检查公钥是否匹配        sk = SigningKey.from_secret_exponent(d, curve=SECP256k1)        vk = sk.verifying_key        if vk.pubkey.point.x() != pub_tuple[0] or vk.pubkey.point.y() != pub_tuple[1]:            return False        # 2. 检查签名 (使用剩余的样本)        for samp in samples:             h_int = samp[&#x27;h&#x27;]            r = samp[&#x27;r&#x27;]            s = samp[&#x27;s&#x27;]                        sig = r.to_bytes(32, &#x27;big&#x27;) + s.to_bytes(32, &#x27;big&#x27;)            h_bytes = h_int.to_bytes(32, &#x27;big&#x27;)                        if not vk.verify_digest(sig, h_bytes, sigdecode=sigdecode_string):                return False        return True    except Exception as e:        return False# ================= 核心攻击逻辑 (SageMath) =================def solve_hnp(samples):    &quot;&quot;&quot;    构造加权格 (Weighted Lattice) 解决 HNP 问题    参考: StackExchange &amp; Boneh-Venkatesan    &quot;&quot;&quot;    msgs = [s[&#x27;h&#x27;] for s in samples]    sigs = [(s[&#x27;r&#x27;], s[&#x27;s&#x27;]) for s in samples]        m = len(msgs)    n = ORDER        # 1. 预处理: 将方程转换为 k - t*d - a = 0 (mod n)    ts = []    as_ = []        for i in range(m):        r, s = sigs[i]        z = msgs[i]                # s * k = z + r * d  =&gt;  k = s^-1 * z + s^-1 * r * d        # Let t = s^-1 * r,  a = s^-1 * z        s_inv = inverse_mod(s, n)        t = (r * s_inv) % n        a = (z * s_inv) % n        ts.append(t)        as_.append(a)    # 2. 构造格    # 我们希望 k 的范围大约在 2^128，而 d 的范围是 2^256    # 为了平衡矩阵，我们需要缩放 k 所在的列，使其范数接近 2^256    scale = 2^(256 - NONCE_BITS)        # 矩阵维度 (m+2) x (m+2)    # 结构:    # [ n*S   0    ...  0    0    0    ] &lt;- 模数行 0    # [ 0     n*S  ...  0    0    0    ] &lt;- 模数行 1    # ...    # [ t0*S  t1*S ...  tm*S 1    0    ] &lt;- 变量 d 的系数行 (Row m)    # [ a0*S  a1*S ...  am*S 0    2^256] &lt;- 常数行 (Row m+1)        B = Matrix(ZZ, m + 2, m + 2)        # 填充模数行    for i in range(m):        B[i, i] = n * scale    # 填充 d 的系数行    for i in range(m):        B[m, i] = ts[i] * scale    B[m, m] = 1        # d 的列    B[m, m+1] = 0    # 填充常数行    for i in range(m):        B[m+1, i] = as_[i] * scale    B[m+1, m] = 0    B[m+1, m+1] = 2^256 # 锚点常数，用于确定是否包含了常数行    log.info(f&quot;格构建完成，维度: &#123;m+2&#125;x&#123;m+2&#125;&quot;)    log.info(&quot;正在执行 LLL 格基规约...&quot;)        # 3. LLL 规约    L = B.LLL()        # 4. 寻找目标向量    # 目标向量形式: (k0*S, k1*S, ..., d, 2^256) 或其相反数    candidates = set()        for row in L:        # 检查最后一列 (锚点)        last_val = row[m+1]                potential_d = None        if last_val == 2^256:            potential_d = row[m]        elif last_val == -2^256:            potential_d = -row[m]                    if potential_d is not None:            d_cand = int(potential_d) % n            if d_cand &gt; 0:                candidates.add(d_cand)                    return list(candidates)# ================= 主程序 =================def main():    context.log_level = &#x27;info&#x27;        # 1. 连接服务器    io = remote(HOST, PORT)        # 接收公钥    line = io.recvline().decode()    pub_data = json.loads(line)    server_pub = (int(pub_data[&#x27;x&#x27;]), int(pub_data[&#x27;y&#x27;]))    log.info(f&quot;服务器公钥: (&#123;hex(server_pub[0])[:10]&#125;..., &#123;hex(server_pub[1])[:10]&#125;...)&quot;)        # 2. 数据采集    all_data = get_signatures(io, COLLECT_COUNT)        train_set = all_data[:ATTACK_COUNT]  # 前6个用于攻击    verify_set = all_data[ATTACK_COUNT:] # 剩余的用于验证        # 3. 执行攻击    log.info(&quot;开始 SageMath 格分析...&quot;)    candidates = solve_hnp(train_set)        log.info(f&quot;LLL 完成，找到 &#123;len(candidates)&#125; 个候选私钥&quot;)        # 4. 验证私钥    priv_key = None    for cand in candidates:        if verify_candidate(cand, verify_set, server_pub):            priv_key = int(cand)            log.success(f&quot;私钥验证成功! d = &#123;hex(priv_key)&#125;&quot;)            break                if priv_key is None:        log.error(&quot;攻击失败，未能恢复有效私钥。&quot;)        io.close()        return    # 5. 伪造签名拿 Flag    log.info(&quot;正在伪造 &#x27;give_me_flag&#x27; 签名...&quot;)    sk = SigningKey.from_secret_exponent(priv_key, curve=SECP256k1)        # 签名目标消息    # 注意：这里我们本地签名，k 是随机安全的，没有问题    msg_bytes = b&quot;give_me_flag&quot;    h_bytes = hashlib.sha256(msg_bytes).digest()    sig = sk.sign_digest(h_bytes, sigencode=sigencode_string)        forge_r = int.from_bytes(sig[:32], &#x27;big&#x27;)    forge_s = int.from_bytes(sig[32:], &#x27;big&#x27;)        # 发送 Payload    payload = json.dumps(&#123;        &quot;op&quot;: &quot;flag&quot;,        &quot;r&quot;: hex(forge_r),        &quot;s&quot;: hex(forge_s)    &#125;)    io.sendline(payload.encode())        # 6. 获取结果    try:        res = io.recvline().decode()        log.success(f&quot;服务器响应: &#123;res&#125;&quot;)    except EOFError:        log.error(&quot;连接意外关闭&quot;)        io.close()if __name__ == &quot;__main__&quot;:    main()
